#include <iostream>
#include <stdexcept>
#include <typeinfo>

class Base {
public:
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    void display() const {
        std::cout << "Derived instance" << std::endl;
    }
};

double computeCircleArea(double radius) {
    if (radius < 0.0) {
        throw std::invalid_argument("Radius cannot be negative");
    }
    return radius * radius * 3.14159;
}

int main() {
    // Test 1: invalid_argument caught polymorphically by std::exception&
    try {
        double area = computeCircleArea(-5.0);
        std::cout << "Area: " << area << std::endl;
    }
    catch (const std::exception& ex) {
        std::cout << "Caught std::exception: " << ex.what() << std::endl;
    }

    // Test 2: bad_cast when dynamic casting reference fails
    Base baseObj;
    try {
        Derived& derivedRef = dynamic_cast<Derived&>(baseObj);
        derivedRef.display();
    }
    catch (const std::bad_cast& ex) {
        std::cout << "Caught bad_cast: " << ex.what() << std::endl;
    }

    std::cout << "Execution continues ..." << std::endl;
    return 0;
}

#include <iostream>
#include <stdexcept>

class TriangleException : public std::logic_error {
private:
    double side1, side2, side3;
public:
    TriangleException(double s1, double s2, double s3)
        : std::logic_error("Invalid triangle sides"),
          side1(s1), side2(s2), side3(s3) {}

    double getSide1() const { return side1; }
    double getSide2() const { return side2; }
    double getSide3() const { return side3; }
};

class Triangle {
private:
    double side1, side2, side3;

    static bool isValid(double a, double b, double c) {
        return (a + b > c) && (a + c > b) && (b + c > a);
    }
public:
    Triangle(double s1, double s2, double s3) {
        if (!isValid(s1, s2, s3)) {
            throw TriangleException(s1, s2, s3);
        }
        side1 = s1;
        side2 = s2;
        side3 = s3;
    }

    double getPerimeter() const {
        return side1 + side2 + side3;
    }
};

int main() {
    try {
        Triangle t1(3.0, 4.0, 5.0);
        std::cout << "Valid triangle perimeter: " << t1.getPerimeter() << std::endl;

        // The following will violate triangle inequality: 1 + 2 <= 5
        Triangle t2(1.0, 2.0, 5.0);
        std::cout << "Perimeter: " << t2.getPerimeter() << std::endl;
    }
    catch (const TriangleException& ex) {
        std::cout << "Caught TriangleException: " << ex.what() << std::endl;
        std::cout << "Offending sides: " << ex.getSide1() << ", "
                  << ex.getSide2() << ", " << ex.getSide3() << std::endl;
    }

    std::cout << "Program finished successfully." << std::endl;
    return 0;
}
